const D=window.STUDY_DATA,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let subject='Physics',chapter='p1',screen='home',progress={};
try{progress=JSON.parse(localStorage.getItem('pcb-boardroom-progress-v1')||'{}');if(!progress||typeof progress!=='object'||Array.isArray(progress))progress={};}catch{progress={}}
const chapterOf=id=>D.chapters.find(c=>c.id===id);
function nav(){
 $('subjects').innerHTML=['Physics','Chemistry','Biology'].map(s=>`<button data-subject="${s}" class="${s===subject?'active':''}" aria-pressed="${s===subject}">${s}</button>`).join('');
 const cs=D.chapters.filter(c=>c.subject===subject);$('chapter-total').textContent=cs.length;
 $('chapters').innerHTML=cs.map(c=>`<button data-chapter="${c.id}" class="${c.id===chapter&&screen==='study'?'active':''}" ${c.id===chapter&&screen==='study'?'aria-current="page"':''}><span class="num">${String(c.number).padStart(2,'0')}</span>${esc(c.title)}</button>`).join('');
}
function sourceLink(r){return `<a target="_blank" rel="noopener" href="${esc(r.url)}">${esc(r.label)}</a>`}
function sourceDetails(r){return `<details class="source-detail"><summary>Original paper · ${esc(r.label)}</summary><p>${sourceLink(r)}</p><p class="muted">${r.url.toLowerCase().endsWith('.pdf')?'Open the PDF':'Download the archive and open'} <strong>${esc(r.file)}</strong>${r.page?` · PDF page ${r.page}`:''}. Use the printed question number to locate it. Archives may contain several sets.</p></details>`}
function refs(p){return `<ul class="refs">${p.refs.map(r=>`<li>${sourceLink(r)}</li>`).join('')}</ul><p class="small muted">Related methods or selected parts, not necessarily identical questions. This is not an exhaustive frequency count or prediction.</p>`}
function questionCard(q){const p=D.patterns.find(p=>p.id===q.family),state=progress[q.id]||'';return `<article class="card" id="${q.id}"><div class="card-top"><span class="pill">${q.ref.year}${q.ref.year===2022?' · Term II':''}</span><span class="muted">Q${esc(q.ref.number)} · ${esc(q.ref.set)}</span>${$('search').value?`<span class="muted">${esc(chapterOf(q.chapter).title)}</span>`:''}</div><h2>${esc(q.title)}</h2><p class="prompt">${esc(q.prompt)}</p><details class="solution"><summary>Show answer & steps</summary><div class="answer"><ol>${q.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div></details>${sourceDetails(q.ref)}${p?`<details class="related-detail"><summary>Practise related PYQs · ${p.years.length} years represented</summary><p>${esc(p.method)}</p><p class="mistake"><strong>Watch out:</strong> ${esc(p.trap)}</p>${refs(p)}</details>`:''}<div class="practice-state"><span>After attempting:</span><button data-state="revise" data-id="${q.id}" aria-pressed="${state==='revise'}" class="${state==='revise'?'selected revise':''}">Need revision</button><button data-state="done" data-id="${q.id}" aria-pressed="${state==='done'}" class="${state==='done'?'selected done':''}">Solved unaided</button></div></article>`}
function patternCard(p){return `<article class="card"><div class="card-top"><span class="pill">Related question family</span><span class="muted">${p.years.length} years represented</span></div><h2>${esc(p.title)}</h2><p>${esc(p.method)}</p><p class="mistake"><strong>Common mistake:</strong> ${esc(p.trap)}</p>${refs(p)}</article>`}
function render(){
 screen='study';nav();$('overview').hidden=true;$('sources-panel').hidden=true;$('study').hidden=false;
 const c=chapterOf(chapter);$('crumb').textContent=`${subject} / Chapter ${c.number}`;$('chapter-title').textContent=c.title;$('chapter-index').textContent=String(c.number).padStart(2,'0');updateProgress();
 const query=$('search').value.trim().toLowerCase(),year=$('year').value,mode=$('mode').value;
 const rows=(mode==='patterns'?D.patterns:D.questions).filter(q=>chapterOf(q.chapter).subject===subject&&(query||q.chapter===chapter)&&(!year||(q.years||[q.ref.year]).includes(+year))&&JSON.stringify(q).toLowerCase().includes(query)&&(mode!=='revision'||progress[q.id]==='revise'));
 $('chapter-notes').innerHTML=query?`<div class="note">Results span all chapters in ${subject}. Clear the search to return to this chapter.</div>`:c.note?`<div class="note">${esc(c.note)}</div>`:'';
 $('count').textContent=`${rows.length} ${mode==='patterns'?'related-question groups':'questions'}${query?' across '+subject:''}`;
 $('results').innerHTML=rows.length?rows.map(mode==='patterns'?patternCard:questionCard).join(''):`<div class="empty">${mode==='revision'?'Nothing marked for revision in this selection yet. Mark a worked question “Need revision” after attempting it.':'No matching questions. Clear your search or choose “All years”.'}</div>`;
}
function updateProgress(){const total=D.questions.filter(q=>q.chapter===chapter).length,done=D.questions.filter(q=>q.chapter===chapter&&progress[q.id]==='done').length;$('chapter-description').textContent=`${total} worked selections · ${done} marked solved unaided. Attempt on paper before opening the answer.`}
function home(){screen='home';nav();$('study').hidden=true;$('sources-panel').hidden=true;$('overview').hidden=false;
 const done=D.questions.filter(q=>progress[q.id]==='done').length,revise=D.questions.filter(q=>progress[q.id]==='revise').length;
 $('overview').innerHTML=`<div class="eyebrow">YOUR BOARD PREP, ONE CHAPTER AT A TIME</div><h1 class="home-title">Practise the question.<br><span>Learn what repeats.</span></h1><p class="lede">A chapter-wise Physics, Chemistry and Biology bank drawn from ten exam years. Start with worked questions, then try related PYQs to check whether you can handle a different version.</p><div class="stats"><div><b>${D.questions.length}</b><span>worked selections</span></div><div><b>${D.patterns.length}</b><span>related-question groups</span></div><div><b>37</b><span>current chapters</span></div></div><div class="progress-box"><div><strong>Your practice</strong><span>${done} solved unaided · ${revise} need revision</span></div><progress max="${D.questions.length}" value="${done}" aria-label="Questions marked solved unaided"></progress><p class="small muted">Saved on this device/browser only. Clearing browser data removes these marks. This is a practice log, not a score prediction.</p></div><h2>Start here if Physics and Chemistry feel weak</h2><div class="start-grid"><button data-start="p3"><span>01 / PHYSICS</span><strong>Current Electricity</strong><small>Start with V = E − Ir and two short numericals.</small></button><button data-start="c3"><span>02 / CHEMISTRY</span><strong>Chemical Kinetics</strong><small>Learn one equation, then change the percentage.</small></button><button data-start="b8"><span>03 / BIOLOGY</span><strong>Microbes in Human Welfare</strong><small>Learn organism–product pairs and their roles.</small></button></div><h2>A practical route toward 90%</h2><div class="plan card"><ol><li><strong>Repair one small concept first.</strong> Read the relevant NCERT section; write its formula or mechanism from memory. Start untimed if the basics are weak.</li><li><strong>Attempt 6–10 questions in writing.</strong> Check units, equations, labels and missing reasoning. Mark mistakes for revision.</li><li><strong>Redo mistakes after 2 days and 7 days.</strong> Count a method as learned when you can solve a changed version without opening the answer.</li><li><strong>Move to full timed papers.</strong> Once most chapters are covered, attempt at least 3 recent papers per subject and check CBSE’s marking schemes. A selected bank cannot replace full-paper practice.</li></ol><div class="note"><strong>Score checkpoint:</strong> 28/30 in practicals requires 62/70 in theory for 90/100 in that subject. Aim for a buffer in timed mocks. Overall board percentage also depends on English and your other counted subjects. No PYQ selection guarantees 90%.</div></div><details class="card"><summary class="strong">Suggested daily block · about 3 hours</summary><p>Physics: 60 minutes concept + written numericals. Chemistry: 60 minutes reactions or calculations. Biology: 40 minutes NCERT recall, diagrams and short answers. Final 20 minutes: redo old mistakes. Adjust to your school workload and rotate chapters so none are left untouched.</p><p>Physics: formula → substitution → result with units. Chemistry: reagent/condition → structure/equation → reason. Biology: precise keywords → separate points → labelled diagram when asked.</p></details><div class="coverage-note"><strong>Scope:</strong> 2016–2020 and 2022–2026; one representative set per subject. 2022 is <strong>Term II only</strong>. This is a curated selection, not all regional sets, all questions or a complete solutions book. Related groups show repeated methods, not predictions.</div><button class="primary" data-start="p3">Start Physics practice →</button> <a class="download" href="PCB-Boardroom.html" download>Download the offline webpage</a>`;
}
function sources(){screen='sources';nav();$('overview').hidden=true;$('study').hidden=true;$('sources-panel').hidden=false;
 $('sources-panel').innerHTML=`<div class="eyebrow">TRANSPARENT SOURCES</div><h1>Papers, syllabus & coverage</h1><p>${esc(D.coverage)}</p><p>The selected 2016 Physics/Chemistry sets carry the suffix /C. Cards may select only one branch or subpart of a longer question.</p><div class="note">Download a CBSE ZIP/RAR archive, extract it and open the listed filename. PDF pages are navigation aids; the printed question number is the definitive reference. A page may show a question’s bilingual starting point.</div><h2>Current official syllabus</h2><ul>${['Physics','Chemistry','Biology'].map(s=>`<li><a href="https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart2/${s}_SecP2_2026-27.pdf" target="_blank" rel="noopener">${s} · 2026–27 syllabus</a></li>`).join('')}</ul><h2>Older topics outside this selection</h2><ul><li><strong>Physics:</strong> communication systems, polarisation, decay-law/half-life numericals, transistors, logic gates and special-purpose semiconductor devices. Several current topics have only qualitative treatment.</li><li><strong>Chemistry:</strong> Surface Chemistry, Isolation of Elements, Polymers and Chemistry in Everyday Life are formative-only in the 2026–27 document. Solid State and the old p-block unit are outside the summative Class XII list used here.</li><li><strong>Biology:</strong> Environmental Issues is formative-only. Old reproduction-in-organisms, food-production strategies, succession and nutrient-cycle questions are not included.</li></ul><p>The official topic list is the authority. All 37 current chapters are represented, but these selections do not cover every assessable concept.</p><h2>Official marking schemes</h2><p><a href="https://www.cbse.gov.in/cbsenew/marking-scheme.html" target="_blank" rel="noopener">CBSE marking-scheme archive</a> · <a href="https://www.cbse.gov.in/cbsenew/question-paper.html" target="_blank" rel="noopener">CBSE question-paper archive</a>. Match the year, subject and paper code. Explanations here are independent study solutions, not official mark allocations.</p><h2>Thirty source papers</h2><div class="table-wrap"><table><thead><tr><th>Year / subject</th><th>Set & filename</th><th>Source</th></tr></thead><tbody>${D.papers.map(p=>`<tr><td>${p.year}${p.year===2022?' · Term II':''}<br>${p.subject}</td><td>${esc(p.set)}<br><small>${esc(p.file)}</small></td><td><a href="${esc(p.source)}" target="_blank" rel="noopener">Download original</a><br><small>${esc(p.note)}</small></td></tr>`).join('')}</tbody></table></div><p class="small muted">Checked ${D.updated}. The cancelled 2021 annual exam is not counted. OCR/text extraction helped search the papers; the public bank is a separately written selection, not a raw OCR transcription.</p>`;
}
function start(id){chapter=id;subject=chapterOf(id).subject;$('search').value='';$('year').value='';$('mode').value='questions';render();$('workspace').scrollIntoView({behavior:'smooth',block:'start'})}
$('subjects').addEventListener('click',e=>{const b=e.target.closest('[data-subject]');if(b)start(D.chapters.find(c=>c.subject===b.dataset.subject).id)});
$('chapters').addEventListener('click',e=>{const b=e.target.closest('[data-chapter]');if(b)start(b.dataset.chapter)});
$('overview').addEventListener('click',e=>{const b=e.target.closest('[data-start]');if(b)start(b.dataset.start)});
$('results').addEventListener('click',e=>{const b=e.target.closest('[data-state]');if(!b)return;const id=b.dataset.id,state=b.dataset.state;progress[id]=progress[id]===state?'':state;try{localStorage.setItem('pcb-boardroom-progress-v1',JSON.stringify(progress))}catch{}b.closest('article').querySelectorAll('[data-state]').forEach(x=>{const a=progress[id]===x.dataset.state;x.setAttribute('aria-pressed',String(a));x.classList.toggle('selected',a);x.classList.toggle('done',a&&x.dataset.state==='done');x.classList.toggle('revise',a&&x.dataset.state==='revise')});if($('mode').value==='revision')render();else updateProgress()});
for(const id of ['search','year','mode'])$(id).addEventListener(id==='search'?'input':'change',render);
$('home-toggle').addEventListener('click',home);$('brand').addEventListener('click',home);$('sources-toggle').addEventListener('click',sources);
$('print').addEventListener('click',()=>{const opened=[];document.querySelectorAll('#results details.solution').forEach(d=>{if(!d.open){d.open=true;opened.push(d)}});window.addEventListener('afterprint',()=>opened.forEach(d=>d.open=false),{once:true});window.print()});
$('year').innerHTML='<option value="">All years</option>'+[2016,2017,2018,2019,2020,2022,2023,2024,2025,2026].reverse().map(y=>`<option value="${y}">${y}${y===2022?' · Term II':''}</option>`).join('');home();
